            uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]

    if AccountType.objects.filter(userId=uniqueId).exists():
        uniqueId="s"
        for r in range(5):
            uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]

    if AccountType.objects.filter(userId=uniqueId).exists():
        uniqueId="r"
        for r in range(5):
            uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]            
    return "".join(['TMUSR',uniqueId])

