def tourIdMaker():

    charList='0123456789qwertyuiopasdfghjklzxcvbnmQWERTYUIOPASDFGHJKLZXCVBNM'
    uniqueId="x"
    for r in range(5):
        uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]

    if Tour.objects.filter(tourId=uniqueId).exists():
        uniqueId="k"
        for r in range(5):
            uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]

    if Tour.objects.filter(tourId=uniqueId).exists():
        uniqueId="p"
        for r in range(5):
            uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]

    if Tour.objects.filter(tourId=uniqueId).exists():
        uniqueId="b"
        for r in range(5):
            uniqueId = uniqueId + charList[math.floor(random.random()*len(charList))]            
    return "".join(['TRAVMAKSTOUR',uniqueId])

def tourDate(sdate):
    print("\n\n",sdate,"\n\n")
    if sdate[4] != '-':
        d,m,y=sdate.split('/')
        fDate = y+'-'+m+'-'+d
        return fDate
    else:
        return sdate

